//	  terms_version,
//	  checkout_key,
//	  payment_due_at
//	FROM orders
//	WHERE id = $1
//	FOR UPDATE
func (q *Queries) LockOrder(ctx context.Context, id uuid.UUID) (Order, error) {
	row := q.db.QueryRow(ctx, lockOrder, id)
	var i Order
	err := row.Scan(
		&i.ID,
		&i.UserID,
		&i.Status,
		&i.SubtotalCents,
		&i.DiscountCents,
		&i.TotalCents,
		&i.DiscountCodeID,
		&i.DiscountCodeSnapshot,
		&i.PickupAt,
		&i.CreatedAt,
		&i.UpdatedAt,
		&i.Code,
		&i.OrderType,
		&i.TermsAcceptedAt,
		&i.TermsVersion,
		&i.CheckoutKey,
		&i.PaymentDueAt,
	)
	return i, err
}

const lockPickupSlot = `-- name: LockPickupSlot :exec
SELECT pg_advisory_xact_lock(
  $1::int,
  (extract(epoch FROM $2::timestamptz) / 60)::int
)
`

type LockPickupSlotParams struct {
	Namespace int32     `json:"namespace"`
	StartsAt  time.Time `json:"startsAt"`
}

// Holds the slot starting at starts_at until the transaction ends, so two
// checkouts cannot both take its last place. The key is the slot's minute since
// the epoch, under a namespace of its own.
//
//	SELECT pg_advisory_xact_lock(
//	  $1::int,
//	  (extract(epoch FROM $2::timestamptz) / 60)::int
//	)
func (q *Queries) LockPickupSlot(ctx context.Context, arg LockPickupSlotParams) error {
	_, err := q.db.Exec(ctx, lockPickupSlot, arg.Namespace, arg.StartsAt)
	return err
}

const nextOrderDayNumber = `-- name: NextOrderDayNumber :one
INSERT INTO order_day_counters (day, last_number)
VALUES ((now() AT TIME ZONE $1::text)::date, 1)
ON CONFLICT (day) DO UPDATE
SET last_number = order_day_counters.last_number + 1
RETURNING day, last_number
`

// The day is read from the transaction's clock, the instant orders.created_at
// takes, so a code and its created_at always name the same bakery day. The row
// lock taken by the upsert holds every other checkout on that day until this
// transaction ends, so numbers are unique and follow each other.
//
//	INSERT INTO order_day_counters (day, last_number)
//	VALUES ((now() AT TIME ZONE $1::text)::date, 1)
//	ON CONFLICT (day) DO UPDATE
//	SET last_number = order_day_counters.last_number + 1
//	RETURNING day, last_number
func (q *Queries) NextOrderDayNumber(ctx context.Context, zone string) (OrderDayCounter, error) {
	row := q.db.QueryRow(ctx, nextOrderDayNumber, zone)
	var i OrderDayCounter
	err := row.Scan(&i.Day, &i.LastNumber)
	return i, err
}

